cd "C:/Users/edmem/OneDrive/Desktop/Minecraft Channel/studio/catalog"; cp /tmp/ov/a.py /tmp/ov/b.py; python - <<'EOF'
import json,sys,os
sys.path.insert(0,'/tmp/ov')
exec(open('/tmp/ov/a.py').read())
b=json.load(open('tag_batches/review_video_1.json',encoding='utf8'))
tx=json.load(open('taxonomy.json',encoding='utf8'))
catmap=lambda f: ('overlay' if f.startswith('Overlays') else 'transition' if f.startswith('Transitions') else 'animation' if f.startswith('Animations') else 'background' if f.startswith('Backgrounds') else 'meme_video' if f.startswith('Meme Videos') else None)
out=[];changes=0;ch=[]
for i,a in enumerate(b['assets']):
    p=a['prev']
    folder=os.path.dirname(a['path']).replace('\\','/')
    t=dict(id=a['id'],description=p['description'],moments=p['moments'],roles=p['roles'],tags=p.get('tags',[]),quote=p.get('quote'),mood=p.get('mood','neutral'),energy=p.get('energy',2),content_rating=p.get('content_rating','clean'),copyright_risk=p.get('copyright_risk','low'),placement=p['placement'],key_mode=p['key_mode'],use_window=p.get('use_window'),volume_db=p.get('volume_db',0),frequency=p.get('frequency','common'),notes=p.get('notes'),category=catmap(folder),folder=folder,clean_name=None,origin='none')
    o=O.get(i,{})
    o=dict(o)
    if 'notes' in o and p.get('notes') and p['notes'].strip() and p['notes'] not in o['notes']:
        o['notes']=o['notes']+" Earlier note: "+p['notes']
    t.update(o)
    if 'folder' in o and 'category' not in o: t['category']=catmap(t['folder'])
    # placement fix for 66 etc unchanged
    prevcmp={k:p.get(k) for k in ('description','moments','roles','placement','key_mode','use_window','notes')}
    if any(t[k]!=prevcmp[k] for k in prevcmp) or t['category']!=a['category'] or t['folder']!=folder:
        changes+=1
    out.append(t)
json.dump(out,open('tags/zz_review_review_video_1.json','w',encoding='utf8'),indent=1,ensure_ascii=False)
# validate
ids=[a['id'] for a in b['assets']]
assert [t['id'] for t in out]==ids and len(set(ids))==len(ids)
cats=tx['categories']; fol=tx['folders']
bad=[]
for t in out:
    for m in t['moments']:
        if m not in tx['moments']: bad.append((t['id'],'moment',m))
    if not 1<=len(t['moments'])<=5: bad.append((t['id'],'nmom'))
    for r in t['roles']:
        if r not in tx['roles']: bad.append((t['id'],'role',r))
    if not 1<=len(t['roles'])<=3: bad.append((t['id'],'nrole'))
    if t['placement'] not in tx['placement']: bad.append((t['id'],'pl'))
    if t['key_mode'] not in tx['key_modes']: bad.append((t['id'],'km',t['key_mode']))
    if t['content_rating'] not in tx['content_rating']: bad.append((t['id'],'cr'))
    if t['copyright_risk'] not in tx['copyright_risk']: bad.append((t['id'],'cp'))
    if t['category'] not in cats: bad.append((t['id'],'cat',t['category']))
    if t['folder'] not in fol: bad.append((t['id'],'folder',t['folder']))
    exp=catmap(t['folder'])
    if exp!=t['category']: bad.append((t['id'],'agree',t['category'],t['folder']))
    uw=t['use_window']
    if uw is not None and not(len(uw)==2 and uw[0]<uw[1]): bad.append((t['id'],'uw'))
print(len(out),changes,bad)
EOF

